260	  useEffect(() => {
261	    if (decks > hadDecks.current) toast.show(decks === 1 ? "A Stream Deck is on this run." : `${decks} Stream Decks are on this run.`);
262	    hadDecks.current = decks;
263	  }, [decks, toast.show]);
264	  // The race this run is in, if any: the side column's panel and the snapshot both read it.
265	  const raceView = useRace(run.record, run.state, run.events);
266	
267	  /**
268	   * The receipts: what each throw of the step did, kept until the step has
269	   * been read.
270	   *
271	   * The engine moves on the instant a roll is answered, so the dice and the
272	   * result would otherwise vanish together. The answer is still committed
273	   * as the engine sees fit, a receipt is a record, not a hold on the game,
274	   * but the step's rolls stay on screen, in order, with the next roll's
275	   * keypad beneath them, until "Carry on" closes the step.
276	   *
277	   * Outcomes are the signal: whatever the run had not resolved before an
278	   * answer, and has now, is what that answer did. Measured from the count
279	   * rather than the request, so a machine roll with auto-roll on, or a move
280	   * that resolves a table, gets a receipt too, just one without dice.
281	   */
282	  const [receipts, setReceipts] = useState<RollReceipt[]>([]);
283	
284	  // Who is on the board, read here as `Moves` reads it: the offer has to
285	  // split a move the same way the panel does. Held by a memo because the
286	  // offer is, and an empty roster built afresh on every render would
287	  // rebuild the offer with it and keep restarting the publish timer.
288	  const racing = useMemo(() => (run.moderated ? (run.state?.contestants ?? []) : []), [run.moderated, run.state]);
289	
290	  /**
291	   * What a deck may press, right now: one value for the snapshot this
292	   * device publishes and for the drive this device takes, so a press is
293	   * always checked against the same offer it was shown.
294	   */
295	  const currentOffer = useMemo(
296	    () =>
297	      offerOf({
298	        seq: run.events.length,
299	        live: Boolean(run.started) && !run.readOnly && run.state?.status !== "ended",
300	        settled: run.pending === null,
301	        step: run.activeStep?.step ?? null,
302	        stepLabel: run.state ? activeStepLabel(pack, run.activeStep) : null,
303	        // A held move -- finalizing, with something still owed -- is the
304	        // page's own button disabled; a deck sees the same offer the page
305	        // would show, so it is left off rather than pressed and refused.
306	        // A move the page splits into a button per racer is left off for
307	        // the same reason: it is not one press on the page either.
308	        moves: run.moves
309	          .filter((m) => !heldMove(m.move, run.blockingObligations.length) && !perRacer(m.move, racing))
310	          .map((m) => ({ id: m.id, label: m.move.label })),
311	        canUndo: run.canUndo,
312	        lastResult: run.state?.outcomes.at(-1) ? entryTextOf(pack, run.state.outcomes.at(-1)!) : null,
313	        owed: run.blockingObligations.length,
314	        // Held to the step's own table, the way the card holds them: a
315	        // step that constrains what may be named suggests only from there.
316	        suggestions: run.state
317	          ? subjectSuggestions(pack, run.state, run.activeStep ? constrainedByOf(run.activeStep.step) : undefined).slice(0, 8)
318	          : [],
319	        // The same button the page itself would show between units: nothing
320	        // else is waiting to be read or answered first, and there is
321	        // nowhere left to go but the unit ahead. Ended, unstarted, watching,
322	        // still asked something, or a receipt still on screen -- none of
323	        // those has a between-units button on the page, so none of them has
324	        // one here.
325	        between:
326	          run.state &&
327	          Boolean(run.started) &&
328	          !run.readOnly &&
329	          run.state.status !== "ended" &&
330	          run.pending === null &&
331	          receipts.length === 0 &&
332	          !run.activeStep
333	            ? run.state.unit === 0
334	              ? `Enter ${pack.vocabulary.unit.one} 1`
335	              : `Enter ${pack.vocabulary.unit.one} ${run.state.unit + 1}`
336	            : null,
337	        // What the step's own button says with every box ticked, in the
338	        // card's words: the closing card's Next, or the manual card's
339	        // Done. Nothing where the step has no list, because there is then
340	        // no list to tick and the primary is the press.
341	        finishLabel: run.activeStep && checklistOf(run.activeStep.step).length > 0 ? finishWords(pack, run.activeStep.step) : null,
342	      }),
343	    [
344	      run.events.length,
345	      run.started,
346	      run.readOnly,
347	      run.state,
348	      run.pending,
349	      run.activeStep,
350	      run.moves,
351	      racing,
352	      run.canUndo,
353	      run.blockingObligations.length,
354	      receipts.length,
355	      pack,
356	    ],
357	  );
358	  useEffect(() => {
359	    if (!api || !publishing || !run.record || !run.state) return;
360	    const record = run.record;
361	    const state = run.state;
362	    const events = run.events;
363	    const race = raceOf(raceView.race, raceView.standings, pack.vocabulary.unit);
364	    const timer = window.setTimeout(() => {
365	      /*
366	       * The control profile rides along: the server reads it there to
367	       * decide what a tool attached to somebody's game should be told.
368	       *
369	       * With the run's setup folded into its terms, because that is what
370	       * a setup is for: one field on the wire, applied on attach, its
371	       * gifts held back on a reconnect by the record the server already
372	       * keeps. A run with a setup and no profile still has something to
373	       * send, which is why the emptiness check comes after the fold.
374	       */
375	      const profile = withChosen((record.control as ControlProfile) ?? {}, chosenFrom(record.setup));
376	      const control = isEmpty(profile) ? {} : { control: tidy(profile) };
377	      void api
378	        .putSnapshot(record.runId, {
379	          ...snapshotOf(pack, state, events, undefined, { race }),
380	          paper: paperOf(pack, state.mode),
381	          offer: currentOffer,
382	          ...control,
383	        })
384	        .catch(() => {});
385	    }, 800);
386	    return () => window.clearTimeout(timer);
387	    // eslint-disable-next-line react-hooks/exhaustive-deps
388	  }, [api, publishing, decks, run.events, pack, raceView.race, run.record?.control, run.record?.setup, currentOffer]);
389	
390	  /**
391	   * Starting a race, or joining one: an ordinary run of this pack with the
392	   * race's seed and mode, and the race told which run this is. Joining a
393	   * race that is for another pack says so rather than guessing.
394	   */
395	  const startRace = async (mode: string, seed: string, runName: string, setup: ChosenSetup | null) => {
396	    if (!api) return;
397	    setRaceNote(null);
398	    const raceId = ulid();
399	    const runId = run.startRun(mode, seed, 1, runName, [], [], { raceId, ...(setup ? { setup } : {}) });
400	    try {
401	      const race = await api.createRace({
402	        id: raceId,
403	        packId: pack.id,
404	        packVersion: pack.version,
405	        packTitle: pack.title,
406	        ...(runName.trim() ? { name: runName.trim() } : {}),
407	        mode,
408	        seed,
409	        sessionId: runId,
410	      });
411	      setRaceNote(`Racing. The code is ${race.meta.code}; it is in the side column too.`);
412	    } catch (error) {
413	      if (error instanceof PlanError)
414	        setRaceNote(`${error.message}. This is an ordinary run for now; subscribe from your profile, under Plan, and start a race again.`);
415	      else setRaceNote(error instanceof Error && error.message ? error.message : "The race could not be started; this is an ordinary run.");
416	    }
417	  };
418	  const joinRace = async (code: string, setup: ChosenSetup | null) => {
419	    if (!api) return;
420	    setRaceNote(null);
421	    try {
422	      const race = await api.joinRace(code);
423	      if (race.meta.packId !== pack.id) {
424	        setRaceNote(`That race is for ${race.meta.packTitle ?? race.meta.packId}. Open that pack and join from there; the code is kept.`);
425	        return;
426	      }
427	      if (!pack.modes[race.meta.mode]) {
428	        setRaceNote(`That race plays a mode this version of the pack does not have (${race.meta.mode}).`);
429	        return;
430	      }
431	      clearPendingRaceCode();
432	      const runId = run.startRun(race.meta.mode, race.meta.seed, 1, race.meta.name ?? "", [], [], {
433	        raceId: race.meta.id,
434	        ...(setup ? { setup } : {}),
435	      });
436	      await api.putRaceEntry(race.meta.id, { sessionId: runId });
437	    } catch (error) {
438	      setRaceNote(error instanceof Error && error.message ? error.message : "That code did not open a race.");
439	    }
440	  };
441	  useAlerts(run.events, run.runId, me, alerts);
442	
443	  const sync = useSync();
444	  // A hosted run opens itself to watchers and sees to a watch key, so an
445	  // address copied from this run works when it is pasted somewhere.
446	  const reachable = useReachable(api, run.record ?? null);
447	  // Whose games this run is holding the other end of, for the badge below.
448	  const tools = useAttachedTools(run.record?.runId ?? null);
449	  // The roller is fetched while the run opens, not when the first die is thrown.
450	  useEffect(() => preloadDice3d(), []);
451	  // Someone else's throw at this table, played here for whoever is not throwing.
452	  const [othersRoll, setOthersRoll] = useState<RolledGesture | null>(null);
453	  useEffect(() => {
454	    const runId = run.record?.runId;
455	    if (!runId) return;
456	    return syncBus.subscribe((news) => {
457	      if (news.t !== "gesture" || news.id !== runId) return;
458	      const rolled = rolledOf(news);
459	      if (rolled) setOthersRoll(rolled);
460	    });
461	  }, [run.record?.runId]);
462	
463	  /**
464	   * A deck's own presses, kept only long enough to answer a retry with
465	   * the same verdict; a run underneath it changing makes a ref from
466	   * before mean nothing, so it is emptied along with the run id.
467	   */
468	  const driveSeen = useRef(new Map<string, Verdict>());
469	  useEffect(() => {
470	    driveSeen.current = new Map();
471	  }, [run.record?.runId]);
472	
473	  /**
474	   * A verdict waiting on the run to catch up.
475	   *
476	   * A deck presses against a `seq`, and the next `seq` it knows about
477	   * arrives with the doorbell, a sync settle away. Pressed twice inside
478	   * that window, the second press named the old one and was refused
479	   * "That moved on." for no reason anybody at the table could see. So an
480	   * accepted verdict waits here until this device's own log has grown,
481	   * and goes out naming what it grew to. A refusal changed nothing and
482	   * goes at once.
483	   *
484	   * The timer is the promise that nothing hangs: a press that somehow
485	   * appended no event is answered anyway, with whatever the run reads at
486	   * by then.
487	   */
488	  const heldVerdict = useRef<{ to: string; ref: string; was: number; timer: number } | null>(null);
