    act(() => {
      syncBus.emit({ t: "gesture", id: "run1", kind: "tools", data: { tools: [], count: 0, decks: 1 }, at });
    });
    expect(notes()).toHaveLength(1);
    expect(notes()[0]!.textContent).toBe("A Stream Deck is on this run.");

