1	import type { Step } from "@runlog/rules-schema";
2	import { checklistOf, closesUnit } from "@runlog/engine";
3	import { pointOf } from "./evidence.ts";
4	
5	/**
6	 * What a deck may press, right now, in the pack's own words.
7	 *
8	 * The same reasoning as `snapshot.asks`: only a device holding the pack
9	 * and the log can say what is on offer, so it is published rather than
10	 * worked out by the server. Wider than `asks`, because a deck is the
11	 * owner pressing and may do what the page's own buttons do.
12	 *
13	 * Deliberately conservative, for the reason `handsFree.ts` gives: this
14	 * removes ceremony, never a decision. Anything the player is genuinely
15	 * being asked, anything owed, and anything typed stops here and says so.
16	 */
17	export interface Offer {
18	  seq: number;
19	  primary: { id: "roll" | "carry-on" | "close" | "enter"; label: string; kind: string } | null;
20	  moves: Array<{ id: string; label: string }>;
21	  undo: { what: string } | null;
22	  /** Why a deck cannot press this, in words a key face can carry. */
23	  needsPage: string | null;
24	  presets: Array<{ kind: string; label: string; suggestions?: string[]; items?: number }>;
25	}
26	
27	export interface OfferInput {
28	  /** The snapshot this offer belongs to; a press carries it back. */
29	  seq: number;
30	  /** Active, editable, and actually started. */
31	  live: boolean;
32	  /** Nothing more is being asked of this step. */
33	  settled: boolean;
34	  step: Step | null;
35	  stepLabel: string | null;
36	  /** What the engine is waiting on, when it is waiting on anything at all. */
37	  request: { kind: "roll"; label: string } | { kind: "other" } | null;
38	  moves: Array<{ id: string; label: string }>;
39	  canUndo: boolean;
40	  lastResult: string | null;
41	  /** Obligations standing in the way. */
42	  owed: number;
43	  /** What the run would suggest for a subject, where it suggests anything. */
44	  suggestions: string[];
45	  /** What the page's between-units button says, or null when the run is not between units. */
46	  between: string | null;
47	  /**
48	   * What the step's own button says once every box is ticked, or null
49	   * where the step has no list. The preset presses that button, so it is
50	   * offered in the words the page uses for it.
51	   */
52	  finishLabel: string | null;
53	}
54	
55	/**
56	 * Steps a key can answer with one press, because they ask nothing first.
57	 *
58	 * A step that closes the unit is not listed here: it is routed by
59	 * `closesUnit` below, the same way whichever kind it is, rather than by
60	 * its own kind.
61	 */
62	const PRESSABLE: Record<string, "roll" | "carry-on" | "close" | "enter"> = {
63	  rollTable: "roll",
64	};
65	
66	/** Steps that take something typed, and the preset that covers each. */
67	const TYPED = new Set(["declareSubject"]);
68	
69	export function offerOf(input: OfferInput): Offer {
70	  const moves = input.moves;
71	  const undo = input.canUndo && input.lastResult ? { what: input.lastResult } : null;
72	  const bare = { seq: input.seq, moves, undo, presets: [] as Offer["presets"] };
73	
74	  // A run nobody is playing -- not started, read-only, ended -- offers
75	  // nothing at all, moves and undo included. They used to ride out on
76	  // `bare`, and `takePress` reads only those two fields when it takes a
77	  // move or an undo, so a deck could move a run the page itself would not
78	  // let anyone touch.
79	  if (!input.live) return { ...bare, moves: [], undo: null, primary: null, needsPage: "Open the run on the page" };
80	  if (!input.step) {
81	    if (input.between) return { ...bare, primary: { id: "enter", label: input.between, kind: "between" }, needsPage: null };
82	    return { ...bare, primary: null, needsPage: null };
83	  }
84	
85	  const step = input.step;
86	  const kind = step.kind;
87	  const label = input.stepLabel ?? "";
88	
89	  // An unsettled step is still being asked something, the same reasoning
90	  // `closesTheUnit` uses to refuse an unsettled unit: it is not yet a bare
91	  // press for a key to make. A pending roll is the one exception: nobody is
92	  // being asked to judge anything, only to throw dice, and a deck can throw
93	  // them the same way the page's own "Roll for me" does.
94	  if (!input.settled) {
95	    if (input.request?.kind === "roll")
96	      return { ...bare, primary: { id: "roll", label: input.request.label, kind: "rollTable" }, needsPage: null };
97	    return { ...bare, primary: null, needsPage: `${label} on the page` };
98	  }
99	
100	  if (TYPED.has(kind))
101	    return {
102	      ...bare,
103	      primary: null,
104	      needsPage: `${label} on the page`,
105	      presets: [{ kind, label, ...(input.suggestions.length > 0 ? { suggestions: input.suggestions } : {}) }],
106	    };
107	
108	  // Owed blocks every bare press but a typed step's own preset: the page
109	  // would refuse the same close or carry-on until it is settled, checked
110	  // once here rather than separately for every kind that reaches this far.
111	  if (input.owed > 0) return { ...bare, primary: null, needsPage: "Something is owed; settle it on the page" };
112	
113	  /*
114	   * Ticking the whole list and pressing the step's own button, for a key
115	   * the streamer put there themselves.
116	   *
117	   * A preset, never the primary: `needsPage` stays, so the follow key goes
118	   * on saying the list is on the page. Pressing this one skips the reading,
119	   * which is a decision, and `handsFree.ts` gives the rule -- a decision is
120	   * skipped only where somebody chose to skip it.
121	   *
122	   * The count is what the step waits for, which is its points less the
123	   * optional ones. Not less the ones with nothing to show: that needs the
124	   * log and the pack, and this says what is on offer from the step alone.
125	   */
126	  const list = checklistOf(step);
127	  const ticking: Offer["presets"] =
128	    list.length > 0 && input.finishLabel
129	      ? [
130	          {
131	            kind: "checklist",
132	            label: `Tick everything and ${input.finishLabel}`,
133	            items: list.map(pointOf).filter((p) => !p.optional).length,
134	          },
135	        ]
136	      : [];
137	
138	  // A step that closes the unit goes to the page's closing card, whichever
139	  // kind it is underneath: a finalizeUnit, or a manual step marked
140	  // closesUnit. Its own confirmation or checklist is the same kind of ask
141	  // as any other and sends it back to the page; empty, it is the one
142	  // press that writes the close, not a step's own carry-on.
143	  if (closesUnit(step)) {
144	    if (list.length > 0) return { ...bare, primary: null, needsPage: `${label} on the page`, presets: ticking };
145	    return { ...bare, primary: { id: "close", label, kind: step.kind }, needsPage: null };
146	  }
147	
148	  // A manual step that does not close the unit asks nothing on its own; it
149	  // only asks something when it carries a checklist to confirm. Empty, it
150	  // is as bare a press as a roll.
151	  if (step.kind === "manual") {
152	    if (list.length > 0) return { ...bare, primary: null, needsPage: `${label} on the page`, presets: ticking };
153	    return { ...bare, primary: { id: "carry-on", label, kind }, needsPage: null };
154	  }
155	
156	  const id = PRESSABLE[kind];
157	  if (!id) return { ...bare, primary: null, needsPage: `${label} on the page` };
158	  return { ...bare, primary: { id, label, kind }, needsPage: null };
159	}

